function diffSets(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) {
    return null;
  }

  const setA = new Set(a);
  const setB = new Set(b);

  const added = [...setB].filter(x => !setA.has(x)).sort();
  const removed = [...setA].filter(x => !setB.has(x)).sort();

  return { added, removed };
