export function pickKeys<T extends object, K extends keyof T>(row: T, keys: readonly K[]): Pick<T, K> {
  if (keys.length === 0) {
    throw new Error('no keys');
  }
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    if (key in row) {
      result[key] = row[key];
    }
  }
  return result;
}

