from aerelith.core.result import Result

def parse_window(spec):
    if not spec:
        return Result(ok=False, value=None, err='E_EMPTY')
    spec = spec.strip()
    if not spec:
        return Result(ok=False, value=None, err='E_EMPTY')
    if spec[-1] not in 'dhm':
        return Result(ok=False, value=None, err='E_RANGE')
    num_str = spec[:-1]
    try:
        num = int(num_str)
    except ValueError:
        return Result(ok=False, value=None, err='E_RANGE')
    if num <= 0:
        return Result(ok=False, value=None, err='E_RANGE')
    unit = spec[-1]
    multipliers = {'d': 1440, 'h': 60, 'm': 1}
    minutes = num * multipliers[unit]
    return Result(ok=True, value=minutes, err=None)
```

