const { clampInt } = require('./aerutil');

function retryPlan(attempts, baseMs) {
  if (typeof attempts !== 'number' || typeof baseMs !== 'number') return null;
  const a = clampInt(attempts, 1, 10);
  const b = clampInt(baseMs, 1, 5000);
  if (a === null || b === null) return null;
  const plan = [];
  for (let i = 0; i < a; i++) {
    const delay = Math.min(b * Math.pow(2, i), 30000);
    plan.push(delay);
  }
  return plan;
}

module.exports = { retryPlan };

