import type { Result } from './result';

export function pickKeys<T extends object, K extends keyof T>(row: T, keys: readonly K[]): Result<Pick<T, K>> {
  if (keys.length === 0) return { ok: false, error: 'no keys' };
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    result[key] = row[key];
  }
  return { ok: true, value: result };
}
