The function iterates over the input array, separating each `Result<T>` into either the `value` (when `ok` is true) or the `error` (when `ok` is false). It collects these into two parallel arrays, preserving the original order. The only edge case is an empty input array, which must result in a failure with the message `'empty'`.

ANSWER:
export function splitOk<T>(rows: readonly Result<T>[]): Result<{ values: T[]; errors: string[] }> {
  if (rows.length === 0) return { ok: false, error: 'empty' };
  const values: T[] = [];
  const errors: string[] = [];
  for (const r of rows) {
    if (r.ok) values.push(r.value);
    else errors.push(r.error);
  }
  return { ok: true, value: { values, errors } };
}

